const product = document.getElementById("product-3");
console.log(product.id);                 // "product-3"
console.log(product.getAttribute("id")); // "product-3" - ten sam wynik

const product = document.getElementById("product-1");
product.setAttribute("title", "Najlepszy laptop");
console.log(product.getAttribute("title")); // "Najlepszy laptop"
product.removeAttribute("title");
console.log(product.getAttribute("title")); // null

const product = document.getElementById("product-1");
for (const [klucz, wartosc] of Object.entries(product.dataset)) {
  console.log(`${klucz}: ${wartosc}`);
}

const product = document.getElementById("product-1");
console.log(product.dataset.price === 599);         // false - string vs liczba
console.log(Number(product.dataset.price) === 599); // true - po konwersji

